sys_script_include.script:
var MediaUtilsClient = Class.create();
MediaUtilsClient.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	getMediaData: function () {
		var mediaSysId = this.getParameter("sysparm_media_sys_id");
		var grMedia = new GlideRecord("x_1974925_nowflix_media");
		grMedia.get(mediaSysId);
		return JSON.stringify({
            current_synopsis: grMedia.getValue("synopsis"),
            current_average_rating: grMedia.getValue("average_rating"),
            poster_url: grMedia.getValue("poster")
		});
	},
    type: 'MediaUtilsClient'
});
